157		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
158		reg(t, s, "B-1", "凭证", "2020-01-01", "2025-01-10")
159		if _, found, err := s.History("A-1"); err != nil || !found {
160			t.Fatalf("损坏前查询应成功: found=%v err=%v", found, err)
161		}
162	
163		// 把 B-1 的当前截止日删掉：B-1 变成无法确认保管期限的档案。
164		rewriteState(t, dir, func(doc map[string]any) {
165			delete(doc["archives"].(map[string]any)["B-1"].(map[string]any), "end")
166		})
167		corruptContent := readStateFile(t, dir)
168	
169		// 重新打开整个位置必须失败，错误指出 B-1 缺的是截止日。
170		s2, err := Open(dir)
171		if err == nil {
172			s2.Close()
173			t.Fatal("任一档案缺当前截止日时，打开必须失败")
174		}
175		if !errors.Is(err, ErrCorruptState) ||
176			!strings.Contains(err.Error(), "B-1") || !strings.Contains(err.Error(), "截止日") {
177			t.Fatalf("打开错误应为 ErrCorruptState 并指出 B-1 缺截止日，得到 %v", err)
178		}
179	
180		// 已打开的实例：即使只操作正常的 A-1，也必须按整库损坏失败。
181		if h, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
182			t.Fatalf("损坏后 History 必须返回 ErrCorruptState 且无结论: found=%v err=%v", found, err)
183		}
184		if _, found, err := s.GetManifest("APP-1"); !errors.Is(err, ErrCorruptState) || found {
185			t.Fatalf("损坏后 GetManifest 必须返回 ErrCorruptState: found=%v err=%v", found, err)
186		}
187		if r, err := s.Check(CheckRequest{
188			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
189		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || len(r.Results) != 0 {
190			t.Fatalf("损坏后 Check 必须失败且不得给出部分报告: %+v err=%v", r, err)
191		}
192		if m, err := s.Destroy(DestructionRequest{
193			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
194		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
195			t.Fatalf("损坏后 Destroy 必须失败且不得生成清册: %+v err=%v", m, err)
196		}
197		if err := s.Register(RegisterInput{ID: "A-2", Category: "凭证", Start: MustParseDate("2020-01-01"), End: MustParseDate("2025-01-10")}); !errors.Is(err, ErrCorruptState) {
198			t.Fatalf("损坏后 Register 必须失败: %v", err)
199		}
200		if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05")}); !errors.Is(err, ErrCorruptState) {
201			t.Fatalf("损坏后 Freeze 必须失败: %v", err)
202		}
203		if _, err := s.Revise(ReviseInput{
204			RevisionID: "REV-1", ArchiveID: "A-1",
205			OriginalEnd: MustParseDate("2025-01-10"), NewEnd: MustParseDate("2026-01-10"),
206			RevisedOn: MustParseDate("2025-01-07"), Reason: "延期",
207		}); !errors.Is(err, ErrCorruptState) {
208			t.Fatalf("损坏后 Revise 必须失败: %v", err)
209		}
210	
211		// 失败不得触发重新保存：损坏内容原样保留，不补日期、不删档案。
212		if got := readStateFile(t, dir); got != corruptContent {
213			t.Fatalf("失败后原保存内容被改动:\n%q", got)
214		}
215	}
216	
217	// 缺当前截止日的档案不能被销毁前核对当成已经到期：损坏发生前该档案
218	// 尚未到期，损坏后核对与正式提交都只能整库失败，绝不能生成清册。
219	func TestMissingEndNeverYieldsDestroyableConclusion(t *testing.T) {
220		dir := t.TempDir()
221		s, err := Open(dir)
222		if err != nil {
223			t.Fatal(err)
224		}
225		defer s.Close()
226		reg(t, s, "A-1", "合同", "2020-01-01", "2099-01-10")
227	
228		// 损坏前：档案未到期，核对给出未到期阻碍而不是可以办理。
229		r, err := s.Check(CheckRequest{
230			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
231		})
232		if err != nil {
233			t.Fatal(err)
234		}
235		if r.Status != CheckBlocked || r.Results[0].Obstructions[0].Kind != ObstructionNotExpired {
236			t.Fatalf("损坏前应判未到期: %+v", r)
237		}
238	
239		// 把截止日删掉：若按零值截止日判断，任何处理日期都会显得已到期。
240		rewriteState(t, dir, func(doc map[string]any) {
241			delete(doc["archives"].(map[string]any)["A-1"].(map[string]any), "end")
242			delete(doc["archives"].(map[string]any)["A-1"].(map[string]any), "initial_end")
243		})
244		corruptContent := readStateFile(t, dir)
245	
246		if r, err := s.Check(CheckRequest{
247			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
248		}); !errors.Is(err, ErrCorruptState) || r.Status != "" {
249			t.Fatalf("缺截止日的档案不得给出核对结论: %+v err=%v", r, err)
250		}
251		if m, err := s.Destroy(DestructionRequest{
252			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
253		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
254			t.Fatalf("缺截止日的档案不得生成清册: %+v err=%v", m, err)
255		}
256		if got := readStateFile(t, dir); got != corruptContent {
257			t.Fatalf("失败后原保存内容被改动:\n%q", got)
258		}
259	}
