198	
199			if anyBlocked {
200				report.Status = CheckBlocked
201			} else {
202				report.Status = CheckReady
203			}
204			return nil
205		})
206		if err != nil {
207			return CheckReport{}, err
208		}
209		return report, nil
210	}
