216			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-2"},
217		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
218			t.Fatalf("损坏后 Destroy 必须失败且不得生成清册: %+v err=%v", m, err)
219		}
220		if err := s.Register(RegisterInput{
221			ID: "A-3", Category: "合同",
222			Start: MustParseDate("2020-01-01"), End: MustParseDate("2025-01-10"),
223		}); !errors.Is(err, ErrCorruptState) {
224			t.Fatalf("损坏后 Register 必须失败: %v", err)
225		}
226		if err := s.Freeze(FreezeInput{
227			ArchiveID: "A-2", FreezeID: "F-1", Reason: "审计", FrozenOn: MustParseDate("2025-01-07"),
228		}); !errors.Is(err, ErrCorruptState) {
229			t.Fatalf("损坏后 Freeze 必须失败: %v", err)
230		}
231		if _, err := s.Revise(ReviseInput{
232			RevisionID: "R-2", ArchiveID: "A-2",
233			OriginalEnd: MustParseDate("2025-01-10"), NewEnd: MustParseDate("2026-01-10"),
234			RevisedOn: MustParseDate("2025-01-07"), Reason: "延期",
235		}); !errors.Is(err, ErrCorruptState) {
236			t.Fatalf("损坏后 Revise 必须失败: %v", err)
237		}
238	
239		// 失败不得触发重新保存：损坏内容原样保留。
240		if got := readStateFile(t, dir); got != corruptContent {
241			t.Fatalf("失败后原保存内容被改动:\n%q", got)
242		}
243	}
244	
245	// 修订关系矛盾出现在另一份档案（含已销毁档案）身上时，打开与后续办理
246	// 同样整库失败，不因本次只操作正常档案而放过异常记录。
247	func TestBrokenRevisionChainOnOtherArchiveFailsWholeVault(t *testing.T) {
248		dir := t.TempDir()
249		s, err := Open(dir)
250		if err != nil {
251			t.Fatal(err)
252		}
253		defer s.Close()
254		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
255		reg(t, s, "D-1", "凭证", "2020-01-01", "2025-01-10")
256		revise(t, s, "R-1", "D-1", "2025-01-10", "2024-06-01", "2024-01-01", "缩短")
257		if _, err := s.Destroy(DestructionRequest{
258			ApplicationID: "APP-D", ProcessedOn: MustParseDate("2024-06-01"), ArchiveIDs: []string{"D-1"},
259		}); err != nil {
260			t.Fatal(err)
261		}
262	
263		// 损坏发生在已销毁档案 D-1 身上：两条修订之间断开。
264		rewriteState(t, dir, func(doc map[string]any) {
265			revisions := doc["archives"].(map[string]any)["D-1"].(map[string]any)["revisions"].([]any)
266			revisions[0].(map[string]any)["new_end"] = "2024-07-01"
267		})
268		corruptContent := readStateFile(t, dir)
269	
270		s2, err := Open(dir)
271		if err == nil {
272			s2.Close()
273			t.Fatal("已销毁档案的修订关系断开时，打开必须失败")
274		}
275		if !errors.Is(err, ErrCorruptState) ||
276			!strings.Contains(err.Error(), "D-1") || !strings.Contains(err.Error(), "R-1") {
277			t.Fatalf("打开错误应为 ErrCorruptState 并指出 D-1/R-1，得到 %v", err)
278		}
279	
280		if _, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found {
281			t.Fatalf("查询无关档案 A-1 也应返回 ErrCorruptState: found=%v err=%v", found, err)
282		}
283		if _, found, err := s.GetManifest("APP-D"); !errors.Is(err, ErrCorruptState) || found {
284			t.Fatalf("查询异常档案所属清册也应失败: found=%v err=%v", found, err)
285		}
286		if r, err := s.Check(CheckRequest{
287			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
288		}); !errors.Is(err, ErrCorruptState) || r.Status != "" {
289			t.Fatalf("核对无关档案也应整次失败: %+v err=%v", r, err)
290		}
291		if m, err := s.Destroy(DestructionRequest{
292			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
293		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
294			t.Fatalf("不得在损坏状态下生成清册: %+v err=%v", m, err)
295		}
296		if got := readStateFile(t, dir); got != corruptContent {
297			t.Fatalf("失败后原保存内容被改动:\n%q", got)
298		}
299	}
