		s := `{"id":"A-1","category":"合同","start":"2020-01-01","end":"` + end +
			`","initial_end":"` + initial + `","destroyed":`
		if destroyed {
			s += `true,"manifest_id":"APP-1"`
		} else {
			s += `false`
		}
